def expanded_form(n):
    digits = str(n)
    parts = []
    for i, d in enumerate(digits):
        place = 10 ** (len(digits) - i - 1)
        if d != "0":
            parts.append(f"{d} x {place:,}")
    return " + ".join(parts)

for n in (4307, 25016, 900050):
    print(f"{n:>7,} = {expanded_form(n)}")

def indian_format(n):
    s = str(n)
    last3, rest = s[-3:], s[:-3]
    groups = []
    while len(rest) > 2:
        groups.insert(0, rest[-2:])
        rest = rest[:-2]
    if rest:
        groups.insert(0, rest)
    return ",".join(groups + [last3]) if groups else last3

for n in (100000, 2500000, 10000000, 123456789):
    print(f"international {n:>13,}    Indian {indian_format(n):>14}")
